mapper.select:
SELECT

FROM t_wallet_flow
WHERE user_id = #{userId}
ORDER BY create_time DESC, id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM t_wallet_flow
WHERE user_id = #{userId}

SELECT IFNULL(SUM(amount), 0)
FROM t_wallet_flow
WHERE user_id = #{userId}

SELECT IFNULL(SUM(amount), 0)
FROM t_wallet_flow
WHERE type = #{type}

    AND user_id <> #{excludeUserId}
